            .await
            .unwrap()
            .unwrap()
            .profile
            .company_number
            .as_deref(),
        Some("00123456")
    );
}

#[sqlx::test(migrations = "../db/migrations", fixtures("declared_totals"))]
async fn declared_totals_include_all_categories_and_preserve_coverage(pool: PgPool) {
    use crate::{
        domain::services::entity_search,
        inbound::http::{routes::routes, state::AppState},
    };
    use std::sync::Arc;
    let db = ExposedDatabase::from(pool);
    let state = AppState {
        entity_search_service: Arc::new(entity_search::Service::new(db.clone(), db.clone())),
        entity_details_service: Arc::new(Service::new(db)),
    };
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let origin = format!("http://{}", listener.local_addr().unwrap());
    let server = tokio::spawn(async move {
        axum::serve(listener, routes().with_state(state))
            .await
            .unwrap();
    });
    let mut expected: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/declared_totals.json")).unwrap();
    let client = reqwest::Client::new();
    for (id, contract) in expected.as_object_mut().unwrap() {
        let before = chrono::Datelike::year(&chrono::Utc::now());
        let response = client
            .get(format!("{origin}/members/{id}"))
            .send()
            .await
            .unwrap();
        assert_eq!(response.status(), reqwest::StatusCode::OK);
        let bytes = response.bytes().await.unwrap();
        let body: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
        let after = chrono::Datelike::year(&chrono::Utc::now());
        let year = body["summary"]["declared_totals"]["calendar_year"]
            .as_i64()
            .unwrap();
        assert!(year == i64::from(before) || year == i64::from(after));
        let period = match (id.as_str(), year) {
            ("7001", 2024) => (Some("300"), 2, false),
            ("7001", 2025) => (Some("25.45"), 6, true),
            ("7002" | "7007", 2025) => (Some("0"), 1, false),
            ("7004", 2025) | ("7006", 2023) => (None, 1, false),
            ("7005", 2025) | ("7007", 2024) => (None, 1, true),
            _ => (None, 0, false),
        };
        contract["declared_totals"]["calendar_year"] = serde_json::json!(year);
        contract["declared_totals"]["current_year"] = serde_json::json!({
            "amount": period.0,
            "declaration_count": period.1,
            "incomplete": period.2,
        });
        assert_eq!(
            body["summary"]["declared_totals"], contract["declared_totals"],
            "member {id}"
        );
    }
    server.abort();
}
import { test as base, expect } from "@playwright/test";
import { createServer, type ServerResponse } from "node:http";
import { spawn } from "node:child_process";
import { once } from "node:events";

type Reply = {
  status?: number;
  body?: string;
  json?: unknown;
  contentType?: string;
};
type BackendRoute = {
  request(): { url(): string };
  fulfill(reply: Reply): Promise<void>;
};
export class Backend {
  handlers: { pattern: string; handle: (route: BackendRoute) => unknown }[] =
    [];
  waiters: {
    predicate: (request: { url(): string }) => boolean;
    resolve: () => void;
  }[] = [];
  async route(pattern: string, handle: (route: BackendRoute) => unknown) {
    this.handlers.push({ pattern, handle });
  }
  async unroute(pattern: string) {
    this.handlers = this.handlers.filter(
      (handler) => handler.pattern !== pattern,
    );
  }
  waitForRequest(predicate: (request: { url(): string }) => boolean) {
    return new Promise<void>((resolve) =>
      this.waiters.push({ predicate, resolve }),
    );
  }
  async respond(url: string, response: ServerResponse) {
    const request = { url: () => url };
    for (const waiter of this.waiters)
      if (waiter.predicate(request)) waiter.resolve();
    const handler = this.handlers.findLast(({ pattern }) =>
      new RegExp(
        "^" +
          pattern
            .split("*")
            .map((part) => part.replace(/[.+?^${}()|[\]\\]/g, "\\$&"))
            .join(".*") +
          "$",
      ).test(url),
    );
    if (!handler) {
      response.writeHead(404).end();
      return;
    }
    await handler.handle({
      request: () => request,
      fulfill: async ({ status = 200, body, json, contentType }) => {
        response.writeHead(status, {
          "content-type":
            contentType ??
            (json === undefined ? "text/plain" : "application/json"),
        });
        response.end(json === undefined ? body : JSON.stringify(json));
      },
    });
  }
}
export const test = base.extend<
  { backend: Backend },
  {
    analytics: boolean;
    development: boolean;
    application: { url: string; backend: Backend };
  }
>({
  analytics: [false, { option: true, scope: "worker" }],
  development: [false, { option: true, scope: "worker" }],
  application: [
    async ({ analytics, development }, use, workerInfo) => {
      const backend = new Backend();
      const server = createServer((req, res) => {
        void backend.respond(`http://127.0.0.1/api${req.url}`, res);
      });
      server.listen(0, "127.0.0.1");
      await once(server, "listening");
      const address = server.address();
      if (!address || typeof address === "string")
        throw new Error("No backend port");
      const port = 4300 + workerInfo.workerIndex;
      const child = spawn(
        process.execPath,
        development
          ? [
              "node_modules/vite/bin/vite.js",
              "--host",
              "127.0.0.1",
              "--port",
              String(port),
              "--strictPort",
            ]
          : ["build"],
        {
          env: {
            ...process.env,
            PUBLIC_POSTHOG_PROJECT_TOKEN: analytics
              ? "phc_test_search_tracking"
              : "",
            PUBLIC_POSTHOG_HOST: analytics ? "https://posthog.test" : "",
            PORT: String(port),
            HOST: "127.0.0.1",
            EXPOSED_API_ORIGIN: `http://127.0.0.1:${address.port}`,
          },
          stdio: "pipe",
        },
      );
      const url = `http://127.0.0.1:${port}`;
      try {
        await expect
          .poll(
            async () => {
              try {
                return (await fetch(url)).status;
              } catch {
                return 0;
              }
            },
            { timeout: 15000 },
          )
