    expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(390);
    if (process.env.EXPOSED_SCREENSHOT_DIR) await page.screenshot({ path: `${process.env.EXPOSED_SCREENSHOT_DIR}/${entity}-periods-narrow.png`, fullPage: true });
